"""Dated institutional forms, courts, sovereign seats and regional events."""
import pathlib,json,urllib.parse
ROOT=pathlib.Path(__file__).resolve().parents[1];OUT=ROOT/'public/data';TAG='support-1500-0.21'
read=lambda f:json.loads((OUT/f).read_text(encoding='utf8'))
save=lambda f,d:(OUT/f).write_text(json.dumps(d,ensure_ascii=False,separators=(',',':'))+'\n',encoding='utf8',newline='\n')
wiki=lambda t:'https://en.wikipedia.org/wiki/'+urllib.parse.quote(t.replace(' ','_'))
def main():
 forms=read('governance.json');forms['records']=[r for r in forms['records'] if r.get('acquisition')!=TAG]
 def form(keys,a,b,tags,title,note=''):
  forms['records'].append(dict(keys=keys.split('|'),start=a,end=b,tags=tags.split('|'),source=wiki(title),sourceLabel='Forma institucional fechada · sigloXVI',priority=15,note=note or 'Clasificación institucional; no una puntuación democrática ni una ideología inferida del color.',acquisition=TAG))
 for keys,tags,title in [
  ('CASTILE|ARAGON|FRA|PRT|ENGLAND|SCOTLAND|SWE|BOHEMIA|HUNGARY-KINGDOM','monarchy|kingdom','Early modern period'),('ESP|KALMAR|DENMARK-NORWAY|HABSBURG-MONARCHY','monarchy|dynastic-union','Personal union'),
  ('MUSCOVY','monarchy|principality','Grand Duchy of Moscow'),('SAXONY-ELECTORATE|ELECTORATE-BRANDENBURG','monarchy|electorate|feudal','Prince-elector'),('BAVARIA-DUCHY|SAVOY-DUCHY|WURTTEMBERG-DUCHY','monarchy|duchy|feudal','Duchy'),('HESSE-UNITED','monarchy|principality|feudal','Landgraviate of Hesse'),
  ('HIST-Q12548','elective-monarchy|empire|feudal','Holy Roman Empire'),('PAPAL-STATES','elective-monarchy|theocracy','Papal States'),('HIST-Q4948|HIST-Q174306|HIST-Q208169','republic|oligarchy|city-state','Maritime republics'),('FLORENCE-REPUBLIC','republic|city-state','Republic of Florence'),('CHE','confederal','Old Swiss Confederacy'),
  ('MING','monarchy|empire','Ming dynasty'),('JOS|AYUTTHAYA','monarchy|kingdom','Early modern period'),('JPN','monarchy|feudal','Sengoku period'),('WATTASID|MAMLUKS|LODI','monarchy|sultanate','Sultanate'),('ETH','monarchy|empire','Ethiopian Empire'),('HIST-Q796583','monarchy|kingdom','Kingdom of Kongo'),('HIST-Q202687','monarchy|empire','Songhai Empire')]:form(keys,1500,1599,tags,title)
 for keys,a,b,tags,title in [
  ('HESSE-UNITED',1500,1567,'monarchy|principality|feudal','Landgraviate of Hesse'),('HESSE-KASSEL|HESSE-DARMSTADT',1567,1599,'monarchy|principality|feudal','Landgraviate of Hesse-Kassel'),('PRUSSIA-DUCHY',1525,1599,'monarchy|duchy|feudal','Duchy of Prussia'),('RUSSIA-TSARDOM',1547,1599,'monarchy|kingdom','Tsardom of Russia'),
  ('FLORENCE-DUCHY',1532,1568,'monarchy|duchy','Duchy of Florence'),('HIST-Q154849',1569,1599,'monarchy|duchy','Grand Duchy of Tuscany'),('POLAND-KINGDOM',1500,1568,'monarchy|kingdom','Kingdom of Poland (1385–1569)'),('POLISH-LITHUANIAN',1569,1599,'elective-monarchy|confederal','Polish–Lithuanian Commonwealth'),('DUTCH-REPUBLIC',1579,1599,'republic|confederal','Union of Utrecht'),('IBERIAN-UNION',1580,1599,'monarchy|dynastic-union','Iberian Union'),
  ('SAFAVID',1501,1599,'monarchy|empire','Safavid Iran'),('HIST-Q33296',1526,1599,'monarchy|empire','Mughal Empire'),('SUR',1540,1556,'monarchy|sultanate','Sur Empire'),('SAADI',1510,1599,'monarchy|sultanate','Saadi dynasty'),('AZTEC',1500,1521,'monarchy|empire','Aztec Empire'),('INCA',1500,1536,'monarchy|empire','Inca Empire'),('NEO-INCA',1537,1572,'monarchy|kingdom','Neo-Inca State'),('EAST-HUNGARY',1526,1570,'monarchy|kingdom','Eastern Hungarian Kingdom')]:form(keys,a,b,tags,title)
 form('FRA',1560,1563,'regency',"Catherine de' Medici")
 form('CASTILE',1507,1516,'regency','Ferdinand II of Aragon')
 form('CASTILE',1516,1517,'regency','Francisco Jiménez de Cisneros')
 form('JPN',1585,1591,'regency','Toyotomi Hideyoshi')
 # Hesse's unified landgraviate does not survive the1567 partition.
 forms['records']=[v for v in forms['records'] if not(v.get('acquisition')==TAG and v['keys']==['HESSE-UNITED'] and v['end']==1599)]
 save('governance.json',forms)
 cs=read('identities.json')['countries'];places=read('historical-places.json');places['records']=[v for v in places['records'] if v.get('acquisition')!=TAG]
 def city(k,n,xy,a=1500,b=1599,aggregate=False):
  v=dict(id='seat021-'+k+'-'+str(a),keys=[k],name=n,coordinates=xy,start=a,end=b,capital=True,role='Sede soberana · Estado agrupado' if aggregate else 'Corte o capital histórica',source='https://www.wikidata.org/wiki/'+cs[k]['qid'],note='Referencia urbana, no perímetro ni frontera de control; las cortes podían ser itinerantes y cambiar durante guerras o exilios.',acquisition=TAG)
  if aggregate:v.update(aggregateKey='HIST-Q12548',entityName=cs[k]['name'],note='Estado incluido en un contorno imperial agregado. La sede abre su ficha independiente sin inventar límites territoriales propios.')
  places['records'].append(v)
 for k,n,xy,a,b in [('BAVARIA-DUCHY','Múnich',[11.582,48.1351],1500,1599),('SAXONY-ELECTORATE','Wittenberg',[12.6484,51.8671],1500,1546),('SAXONY-ELECTORATE','Dresde',[13.7373,51.0504],1547,1599),('HESSE-UNITED','Kassel',[9.4797,51.3127],1500,1566),('HESSE-KASSEL','Kassel',[9.4797,51.3127],1567,1599),('HESSE-DARMSTADT','Darmstadt',[8.6512,49.8728],1567,1599),('WURTTEMBERG-DUCHY','Stuttgart',[9.1829,48.7758],1500,1599)]:city(k,n,xy,a,b,True)
 for k,n,xy,a,b in [
  ('FRA','París',[2.3522,48.8566],1500,1599),('CASTILE','Valladolid · sede de la corte',[-4.7286,41.6523],1500,1515),('ARAGON','Zaragoza · instituciones deAragón',[-.8891,41.6488],1500,1599),('ESP','Madrid · corte',[-3.7038,40.4168],1561,1599),('PRT','Lisboa',[-9.1393,38.7223],1500,1599),
  ('ENGLAND','Londres',[-.1278,51.5074],1500,1599),('SCOTLAND','Edimburgo',[-3.1883,55.9533],1500,1599),('MUSCOVY','Moscú',[37.6173,55.7558],1500,1546),('RUSSIA-TSARDOM','Moscú',[37.6173,55.7558],1547,1599),('PAPAL-STATES','Roma',[12.4964,41.9028],1500,1599),
  ('MING','Pekín',[116.4074,39.9042],1500,1599),('JOS','Hanseong',[126.978,37.5665],1500,1599),('JPN','Kioto · corte imperial',[135.7681,35.0116],1500,1599),('SAFAVID','Tabriz',[46.2919,38.0962],1501,1554),('SAFAVID','Qazvín',[50.0033,36.2688],1555,1597),('SAFAVID','Isfahán',[51.6776,32.6546],1598,1599),('AYUTTHAYA','Ayutthaya',[100.5574,14.3532],1500,1599),('OTT','Constantinopla',[28.9784,41.0082],1500,1599),
  ('AZTEC','México-Tenochtitlan',[-99.1332,19.4326],1500,1521),('INCA','Cusco',[-71.9675,-13.5319],1500,1536),('NEO-INCA','Vilcabamba · región de referencia',[-72.975,-13.121],1537,1572),('HIST-Q33296','Agra',[78.0081,27.1767],1526,1540),('HIST-Q33296','Agra',[78.0081,27.1767],1556,1570),('HIST-Q33296','Fatehpur Sikri',[77.6679,27.0945],1571,1585),('HIST-Q796583','Mbanza Kongo',[14.2485,-6.267],1500,1599),('HIST-Q4948','Venecia',[12.3155,45.4408],1500,1599),('HIST-Q174306','Génova',[8.9463,44.4056],1500,1599),('FLORENCE-REPUBLIC','Florencia',[11.2558,43.7696],1500,1531),('FLORENCE-DUCHY','Florencia',[11.2558,43.7696],1532,1568),('HIST-Q154849','Florencia',[11.2558,43.7696],1569,1599)]:city(k,n,xy,a,b)
 save('historical-places.json',places)
 context=read('historical-context.json');history=read('country-history.json');points=read('conflict-points.geojson')
 for data,field in [(context,'events'),(history,'records')]:data[field]=[v for v in data[field] if not v['id'].startswith('review021-')]
 points['features']=[v for v in points['features'] if not str(v['id']).startswith('review021-')]
 rows=[
  ('crowns','transition','CASTILE|ARAGON|ESP',1500,1556,'Coronas hispánicas · sucesión y regencias','Castilla yAragón tienen instituciones y sucesiones propias. Juana reina legalmente; Fernando yCisneros ejercen regencias distintas del co-reinado deCarlos. No se anticipa aCarlosI a1500.','Joanna of Castile',None),
  ('italian','conflict','FRA|ESP|HABSBURG-MONARCHY|HIST-Q12548|HIST-Q153529|HIST-Q173065|PAPAL-STATES|HIST-Q4948',1500,1559,'Guerras deItalia · tramo observado','Conjunto de campañas, alianzas y ocupaciones iniciado en1494. Marignano,Pavía y el saqueo deRoma son eventos distintos; el punto regional no reconstruye frentes militares.','Italian Wars',[10.5,43.5]),
  ('reformation','transition','HIST-Q12548|SAXONY-ELECTORATE|HESSE-UNITED|ENGLAND|PAPAL-STATES',1517,1555,'Reforma y transformaciones institucionales','Reforma religiosa y cambios políticos diversos. La paz deAugsburgo de1555 no convierte todo elSacroImperio a una confesión ni determina automáticamente una etiqueta democrática.','Reformation',None),
  ('schmalkaldic','conflict','HIST-Q12548|SAXONY-ELECTORATE|HESSE-UNITED',1546,1547,'Guerra deEsmalcalda','Conflicto imperial con laLiga deEsmalcalda; el traslado de la dignidad electoral sajona en1547 se distingue del cambio de todas las fronteras alemanas.','Schmalkaldic War',[11.5,50.5]),
  ('tudor','transition','ENGLAND|SCOTLAND',1509,1600,'Tudor y sucesiones británicas','EnriqueVIII,EduardoVI,la proclamación disputada deJuanaGrey,MaríaI eIsabelI tienen intervalos distintos. Escocia conserva su corona; no se anticipa la unión de1603.','House of Tudor',None),
  ('french-religion','conflict','FRA|ESP|ENGLAND',1562,1598,'Guerras de religión deFrancia','Conflictos entre facciones religiosas y dinásticas, con intervención exterior. La sucesión deEnriqueIV de1589 y elEdicto deNantes de1598 son hitos distintos; un color monárquico no acredita control uniforme.','French Wars of Religion',[2,46]),
  ('dutch','conflict','ESP|DUTCH-REPUBLIC',1568,1599,'Revuelta neerlandesa · tramo del sigloXVI','Unión deUtrecht en1579 y abjuración de1581 preceden al reconocimiento de1648. La ventana termina en1599 por cobertura, no por el final de la guerra.','Eighty Years War',[4.5,51.5]),
  ('iberian','transition','ESP|PRT|IBERIAN-UNION',1580,1599,'Unión ibérica · coronas distintas','La crisis sucesoria portuguesa lleva al monarca compartido. FelipeI dePortugal esFelipeII deEspaña; sus instituciones y administraciones no se fusionan en un Estado nacional único.','Iberian Union',None),
  ('mexico','conflict','AZTEC|CASTILE|ESP',1519,1521,'Conquista deMéxico-Tenochtitlan','La guerra incorpora alianzas indígenas, epidemias y el sitio deTenochtitlan. Captura deCuauhtémoc en1521: su ejecución de1525 no prolonga el control del imperio hasta esa fecha.','Spanish conquest of the Aztec Empire',[-99.1332,19.4326]),
  ('inca','conflict','INCA|NEO-INCA|ESP',1532,1572,'Conquista andina y resistencia deVilcabamba','La captura deAtahualpa y el derrumbe imperial no extinguen toda resistencia. Vilcabamba1537–1572 tiene un ámbito distinto y menor; la geometría de fuente puede conservar un contorno agregado que no acredita su territorio preciso.','Neo-Inca State',[-72.2,-13.3]),
  ('muscovy','transition','MUSCOVY|RUSSIA-TSARDOM',1533,1547,'Moscovia y título de zar','IvánIV accede como gran príncipe en1533; el título de zar comienza en1547. Minoría y regencias no son un reinado adulto continuo.','Ivan the Terrible',None),
  ('mughal','conflict','LODI|SUR|HIST-Q33296',1526,1556,'Mogoles,Lodi y poder surí','Panipat en1526,el poder surí1540–1555 y la restauración deHumayun son fases distintas. No se interpola su reinado a través de su exilio.','Mughal Empire',[77,28]),
  ('hungary','conflict','OTT|HUNGARY-KINGDOM|EAST-HUNGARY|HABSBURG-MONARCHY',1526,1570,'Hungría · sucesión disputada y partición','Después deMohács coexisten las pretensiones deFernando yJuanZápolya, la expansión otomana y el reino oriental. No se atribuye el agregado jagellón a un único rey polaco.','Eastern Hungarian Kingdom',[19.05,47.5]),
  ('japan','transition','JPN',1500,1599,'Japón · Sengoku y consolidación del poder','Corte imperial,shogunes Ashikaga y poderes regionales coexisten. Oda yToyotomi no ostentan el título de shogun. La concentración del poder no permite pintar retrospectivamente todos los dominios como un Estado centralizado.','Sengoku period',None),
  ('imjin','conflict','JPN|JOS|MING',1592,1598,'Invasiones japonesas deCorea','Dos campañas y una fase de negociaciones, con intervención Ming. El marcador es una referencia regional; no se inventan superficies precisas de ocupación a partir de ese punto.','Japanese invasions of Korea (1592–1598)',[127.5,36.5]),
  ('songhai','conflict','HIST-Q202687|SAADI',1591,1599,'Songhai · conquista y poderes sucesores','La invasión saadí no convierte toda la región en una administración uniforme: elPashalik deTombuctú y la resistencia deDendi requieren series propias. Los contornos anteriores no certifican su control posterior.','Moroccan invasion of the Songhai Empire',[-2,17]),
  ('mamluks','conflict','MAMLUKS|OTT',1516,1517,'Conquista otomana del sultanato mameluco','La caída del sultanato y su reorganización administrativa se distinguen de una mera sucesión dinástica. Las autoridades otomanas no se anticipan a los años mamelucos.','Ottoman–Mamluk War (1516–1517)',[32,30])]
 for id,kind,keys,a,b,title,text,ref,xy in rows:
  e=dict(id='review021-'+id,type=kind,countries=keys.split('|'),title=title,start=f'{a}-01-01',end=f'{b+1}-01-01',text=text,source=wiki(ref),sourceLabel='Referencia documental · sigloXVI',precision=9,startIsCoverageBoundary=True,endIsCoverageBoundary=True,note='Síntesis anual parcial; no una geometría diaria de control.')
  if id=='mexico':e['source']='https://www.metmuseum.org/essays/tenochtitlan'
  if id=='tudor':e['source']='https://www.hrp.org.uk/hampton-court-palace/history-and-stories/henry-viiis-children/'
  context['events'].append(e);history['records'].append(dict(id=e['id'],keys=e['countries'],section='history' if kind=='conflict' else 'institutions',**{k:v for k,v in e.items() if k not in ['id','countries','type']}))
  if xy:points['features'].append(dict(type='Feature',id=e['id'],geometry=dict(type='Point',coordinates=xy),properties=dict(name=title,countries=e['countries'],kind='regional-conflict',start=e['start'],end=f'{b}-12-31',precision=9,source=e['source'],sourceLabel=e['sourceLabel'],note=text+' Referencia regional, no superficie ocupada.')))
 context['startYear']=1500;history['coverageStart']=1500;save('historical-context.json',context);save('country-history.json',history);save('conflict-points.geojson',points)
 print('Forms',len(forms['records']),'places',len(places['records']),'new context',len(rows))
if __name__=='__main__':main()
